/* Replaces the moby with a broken copy (type 0x43C); with burst set, also throws 50 pieces around it. */
void spawn_moby_breakup_effect(char *m, int burst) {
    char *n;
    float w[4];
    float v[4];
    int i;
    *(int *)(((char *)((Moby *)m)->pvars) + 4) = 0;
    n = CreateMoby(0x43C);
    *(short *)(n + 0x32) = 0x40;
    n[0x31] = 1;
    *(long *)(n + 0x38) = *(long *)(m + 0x38);
    *(short *)(n + 0x34) = ((Moby *)m)->flags;
    qcopy(n + 0x10, m + 0x10);
    qcopy(n + 0x40, m + 0x40);
    *(float *)(n + 0x2C) = ((Moby *)m)->scale;
    moby_build_matrix(n);
    ((Moby *)m)->flags |= 1;
    if (burst != 0) {
        for (i = 0; i < 50; i++) {
            float spd = random_float_between(1.0f, 6.0f) * g_frame_time;
            float a = random_angle_radians();
            float c = FastCos(a);
            float s;
            v[0] = c + c;
            s = FastSin(a);
            v[1] = s + s;
            v[2] = 0.0f;
            FastVecAdd(w, m + 0x10, v);
            w[2] += random_float_between(*(float *)&blarg_tube_base_z + 0.5f, *(float *)&blarg_tube_base_z + 4.5f);
            vec_scale_to_length(v, v, spd);
            spawn_spinning_moby_fragment(m, w, v);
        }
    }
}
