/* 2 for a moby in state 7, 1 above state 3, else 0. Adapted from Lombyte's project (GPL-3.0) for PAL: src/overlays/l06/gameplay/entities/002fd1a0.c, FUN_L06_003047f8. */
s32 get_red_button_sequence_status(const u8 *moby) {
    u32 state = moby[0x20];

    if (state == 7) {
        return 2;
    }
    if (state > 3) {
        return 1;
    }
    return 0;
}
