/* draws four copies of a model transformed by a table, then spawns a part for each */
void draw_moby_vector_streams(char *m) {
    float a[16];
    float b[16];
    float mat[5][16];
    int s[10];
    char *data;
    float *m0;
    int *sp;
    float *pp;
    float *tp;
    float *mp;
    int i;
    int j;
    data = ((char *)((Moby *)m)->pvars);
    euler_to_matrix(a, (float *)(m + 0x40));
    set_scale_matrix(b, *(float *)&vector_stream_matrix_scale);
    sce_vu0_mul_matrix(a, a, b);
    VU1_addGSregister(6, GetEffectTex(0xE));
    VU1_addGSregister(0x14, 0xFF9000000260L);
    VU1_addGSregister(8, 0);
    VU1_addGSregister(0x42, (long)*(int *)&vector_stream_alpha_a | ((long)*(int *)&vector_stream_alpha_b << 2) | ((long)*(int *)&vector_stream_alpha_c << 4) | ((long)*(int *)&vector_stream_alpha_d << 6) | 0x8000000000L);
    font_queue_vu_state();
    m0 = mat[0];
    sp = s;
    pp = mat[0] + 12;
    tp = vector_stream_rotations;
    mp = m0;
    for (i = 0; i < 4; i++) {
        euler_to_matrix(mp, tp);
        tp += 4;
        sce_vu0_mul_matrix(mp, a, mp);
        mp += 16;
        FastVecAdd(pp, pp, m + 0x10);
        pp[2] += (float)i * 1.7f + 0.6f;
        pp[3] = 1.0f;
        pp += 16;
    }
    s[0] = vector_stream_regen_ticks;
    s[2] = (int)(data + 0xF00);
    s[1] = vector_stream_fade_ticks;
    s[3] = *(int *)&vector_stream_color_a;
    s[4] = *(int *)&vector_stream_color_b;
    *(float *)&s[7] = *(float *)&vector_stream_texture_u_step;
    *(float *)&s[8] = *(float *)&vector_stream_uv_scroll;
    s[5] = 0x1E;
    s[6] = (int)data;
    pp = m0;
    for (j = 3; j >= 0; j--) {
        blarg_draw_strand_strip(sp, pp);
        pp += 16;
    }
}
